import {it,expect,vi} from 'vitest'
import {MultiCatalog} from './multi-catalog'
import {multiFixture} from './multi-fixture'
import {roleFixture} from './role-fixture'
const H='a'.repeat(64),url='/listen/multi-layering/v1/'+H+'.json'
function setup(){const approval=multiFixture(),entry:any={id:approval.base.id,sourcePosition:40},events:string[]=[],extra={approval,buffers:new Map(),release:vi.fn()},ready:any={approval:approval.base,release:vi.fn()},base:any={load:vi.fn(async()=>[]),candidates:vi.fn(()=>[entry]),prepare:vi.fn(async()=>{events.push('base');return ready}),dispose:vi.fn()},read=vi.fn(async(path:string)=>new TextEncoder().encode(JSON.stringify(path.endsWith('index.json')?{schema:'harbeat.multi-layering-index.v1',scenes:[{baseId:approval.base.id,sha256:H,url,sources:1}]}:approval)).buffer),prepareExtra=vi.fn(async()=>{events.push('extra');return extra}),catalog=new MultiCatalog(base,{} as any,{} as any,new URL('https://example.test'),'c',{read,digest:async()=>H,prepareExtra});return{approval,entry,events,extra,ready,base,read,prepareExtra,catalog}}
it('prepares extra workspace before AB and releases every owner once',async()=>{const f=setup();await f.catalog.load(new AbortController().signal);const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(f.events).toEqual(['extra','base']);expect(r.multi).toBe(f.extra);r.release();r.release();expect(f.extra.release).toHaveBeenCalledTimes(1);expect(f.ready.release).toHaveBeenCalledTimes(1)})
it('keeps exact original AB when C is absent or fails; aborted requests do not start AB',async()=>{const f=setup();await f.catalog.load(new AbortController().signal);f.prepareExtra.mockRejectedValue(Error('late C'));const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(r).toBe(f.ready);const c=new AbortController();c.abort();await expect(f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,c.signal)).rejects.toThrow();expect(f.base.prepare).toHaveBeenCalledTimes(1)})
it('discards an altered extra reference but keeps freshly verified AB',async()=>{const f=setup();await f.catalog.load(new AbortController().signal);f.ready.approval={...f.approval.base,id:'e'.repeat(64)};const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(r).toBe(f.ready);expect(f.extra.release).toHaveBeenCalled();expect(f.ready.release).not.toHaveBeenCalled()})
it('releases extra retained memory and retries original AB after a budget failure',async()=>{const f=setup();await f.catalog.load(new AbortController().signal);f.base.prepare.mockRejectedValueOnce(Error('workspace budget'));const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(r).toBe(f.ready);expect(f.extra.release).toHaveBeenCalledTimes(1);expect(f.base.prepare).toHaveBeenCalledTimes(2)})
it('reserves cue preparation time for AB and skips late C',async()=>{const f=setup();await f.catalog.load(new AbortController().signal);const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>30,new AbortController().signal);expect(r).toBe(f.ready);expect(f.prepareExtra).not.toHaveBeenCalled()})

function roleSetup(mode:'roles-c'|'roles-cd'='roles-c'){
 const approval=roleFixture(mode);approval.base.sceneSha256=H
 const entry:any={id:approval.base.id,sourcePosition:40},events:string[]=[],extra={approval,buffers:new Map(),release:vi.fn()},ready:any={approval:approval.base,release:vi.fn()},base:any={load:vi.fn(async()=>[]),candidates:vi.fn(()=>[entry]),prepare:vi.fn(async()=>{events.push('base');return ready}),dispose:vi.fn()}
 const read=vi.fn(async(path:string)=>new TextEncoder().encode(JSON.stringify(path.endsWith('index.json')?{schema:'harbeat.role-replacement-index.v1',scenes:[{baseId:approval.base.id,sha256:H,url:'/listen/role-replacement/v1/'+H+'.json',sources:mode==='roles-cd'?2:1}]}:approval)).buffer),prepareRoles=vi.fn(async()=>{events.push('roles');return extra}),catalog=new MultiCatalog(base,{}as any,{}as any,new URL('https://example.test'),mode,{read,digest:async()=>H,prepareRoles})
 return{approval,entry,events,extra,ready,base,read,prepareRoles,catalog}
}
it('loads role approvals from their independent route and retains replacements beside the exact original AB',async()=>{
 for(const mode of ['roles-c','roles-cd'] as const){const f=roleSetup(mode);await f.catalog.load(new AbortController().signal);const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(f.read.mock.calls[0][0]).toBe('/listen/role-replacement/v1/index.json');expect(f.events).toEqual(['roles','base']);expect(r.roles).toBe(f.extra);expect(r.multi).toBeUndefined();expect(r.approval).toBe(f.ready.approval);r.release();r.release();expect(f.extra.release).toHaveBeenCalledTimes(1);expect(f.ready.release).toHaveBeenCalledTimes(1)}
})
it('missing, research-only, changed hash, wrong mode and changed base roles retain unmodified AB',async()=>{
 for(const change of [(f:any)=>f.approval.approved=false,(f:any)=>f.approval.evidence.measurementsSha256='e'.repeat(64),(f:any)=>f.approval.mode='roles-cd',(f:any)=>f.read.mockRejectedValueOnce(Error('missing index')),(f:any)=>f.ready.approval={...f.approval.base,id:'e'.repeat(64)}]){const f=roleSetup();change(f);await f.catalog.load(new AbortController().signal);const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,new AbortController().signal);expect(r).toBe(f.ready);expect(r.roles).toBeUndefined()}
})
it('late or oversized replacement preparation releases its owner and leaves AB preparation available',async()=>{
 const f=roleSetup();await f.catalog.load(new AbortController().signal);let position=0;f.prepareRoles.mockImplementation(async()=>{position=30;return f.extra});const r=await f.catalog.prepare(f.entry,{}as any,{}as any,()=>position,new AbortController().signal);expect(r).toBe(f.ready);expect(f.extra.release).toHaveBeenCalledOnce()
 const x=roleSetup('roles-cd');await x.catalog.load(new AbortController().signal);x.base.prepare.mockRejectedValueOnce(Error('memory'));expect(await x.catalog.prepare(x.entry,{}as any,{}as any,()=>0,new AbortController().signal)).toBe(x.ready);expect(x.extra.release).toHaveBeenCalledOnce();expect(x.base.prepare).toHaveBeenCalledTimes(2)
})
it('cancels an in-flight role decode without installing a late result or starting stale AB',async()=>{
 const f=roleSetup(),c=new AbortController();await f.catalog.load(c.signal);f.prepareRoles.mockImplementation(async()=>{c.abort();return f.extra});await expect(f.catalog.prepare(f.entry,{}as any,{}as any,()=>0,c.signal)).rejects.toThrow();expect(f.extra.release).toHaveBeenCalledOnce();expect(f.base.prepare).not.toHaveBeenCalled()
})
